--
-- Table structure for table `asset_account`
--

DROP TABLE IF EXISTS `asset_account`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `asset_account` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '账户ID',
  `user_id` bigint NOT NULL COMMENT '所属用户',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '账户名称（如 招商银行、花呗）',
  `type` tinyint NOT NULL COMMENT '账户类型：1-bank，2-platform，3-credit_wallet，4-wallet',
  `platform_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '平台标识（如 ALIPAY、MEITUAN）',
  `account_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '银行卡号/平台账号',
  `balance` decimal(18,2) DEFAULT '0.00' COMMENT '账户余额',
  `is_virtual` tinyint(1) DEFAULT '0' COMMENT '是否为虚拟账户',
  `credit_limit` decimal(18,2) DEFAULT NULL COMMENT '信用额度，仅信用钱包用',
  `currency` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT 'CNY' COMMENT '币种',
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '账户描述',
  `created_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '修改人',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `is_deleted` tinyint DEFAULT '0' COMMENT '是否删除（0-否，1-是）',
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `asset_account_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='资产账户表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `asset_account`
--

